/**
 * Archive decoding: the two decoders the toolchain installer depends on.
 *
 * The LZMA1 fixtures are Python's `liblzma` output (committed, regenerated by
 * `make-lzma-fixtures.py`), because a decoder only proves itself against a
 * reference encoder — this is the test that caught the normalisation bug the
 * real KiCad archive exposed (83548 of its entries are method 14).
 *
 * The ZIP cases are synthesised with `fflate` at test time, so traversal,
 * limits and prefix stripping are pinned without shipping a binary fixture.
 */
import { mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { zipSync } from 'fflate'
import {
  LZMA_ZIP_HEADER_BYTES, LzmaError, decodeLzma, parseLzmaProperties, readZipLzmaHeader,
} from '../../src/toolchain/lzma.js'
import {
  DEFAULT_ZIP_LIMITS, ZipError, commonDirectory, extractZip, readZipDirectory, readZipEntry, safeEntrySegments,
} from '../../src/toolchain/zip.js'

interface LzmaCase {
  readonly name: string
  readonly plainBytes: number
  readonly plainHex: string
  readonly streamHex: string
  readonly propsHex: string
}

let cases: LzmaCase[] = []

beforeAll(async () => {
  const raw = await readFile(new URL('./fixtures/lzma-cases.json', import.meta.url), 'utf8')
  cases = JSON.parse(raw) as LzmaCase[]
})

describe('LZMA1 decoder', () => {
  it('reads properties in both the raw and the ZIP-header shape', () => {
    const properties = parseLzmaProperties(Buffer.from([0x5d, 0x00, 0x00, 0x80, 0x00]))
    expect(properties).toMatchObject({ lc: 3, lp: 0, pb: 2, dictSize: 1 << 23 })
    // A ZIP method-14 entry carries a 2-byte version, 2-byte property size, then
    // the 5 property bytes.
    const zipHeader = Buffer.from([0x09, 0x14, 0x05, 0x00, 0x5d, 0x00, 0x00, 0x80, 0x00])
    const read = readZipLzmaHeader(zipHeader)
    expect(read.properties).toMatchObject({ lc: 3, pb: 2 })
    // Consumed covers the 4-byte method header plus the 5 property bytes.
    expect(read.consumed).toBe(LZMA_ZIP_HEADER_BYTES + 5)
  })

  it('refuses a property block the format cannot describe', () => {
    // 0xff decodes to pb=5, one past the format's own limit; a short block has
    // no dictionary size at all.
    expect(() => parseLzmaProperties(Buffer.from([0xff, 0x00, 0x00, 0x80, 0x00]))).toThrow(LzmaError)
    expect(() => parseLzmaProperties(Buffer.from([0x5d, 0x00]))).toThrow(LzmaError)
  })

  it('reproduces liblzma byte-for-byte for every committed fixture', () => {
    expect(cases.length).toBeGreaterThan(0)
    for (const fixture of cases) {
      const plain = decodeLzma(
        Buffer.from(fixture.streamHex, 'hex'),
        parseLzmaProperties(Buffer.from(fixture.propsHex, 'hex')),
        fixture.plainBytes,
      )
      expect(plain.toString('hex'), fixture.name).toBe(fixture.plainHex)
    }
  })

  it('refuses an output size the stream cannot fill', () => {
    const fixture = cases[0]
    expect(fixture).toBeDefined()
    if (fixture === undefined) return
    expect(() => decodeLzma(
      Buffer.from(fixture.streamHex, 'hex'),
      parseLzmaProperties(Buffer.from(fixture.propsHex, 'hex')),
      fixture.plainBytes + 64,
    )).toThrow(LzmaError)
  })
})

/** A flat archive: no common prefix, one deflated pair and one stored byte. */
function flatArchive(): Uint8Array {
  return zipSync({
    'bin/kicad-cli.exe': new TextEncoder().encode('MZ'.repeat(400)),
    'docs/readme.txt': new TextEncoder().encode('KiCad HuaQiu\n'),
    'empty.txt': new Uint8Array(0),
  })
}

describe('ZIP reader', () => {
  let root: string

  beforeAll(async () => {
    root = await mkdtemp(join(tmpdir(), 'hardware-zip-'))
  })

  afterAll(async () => {
    await rm(root, { recursive: true, force: true })
  })

  const write = async (name: string, bytes: Uint8Array): Promise<string> => {
    const path = join(root, name)
    await writeFile(path, bytes)
    return path
  }

  it('reads the central directory with sizes and methods', async () => {
    const archive = await write('flat.zip', flatArchive())
    const directory = await readZipDirectory(archive)
    expect(directory.entries.map(entry => entry.name)).toEqual(['bin/kicad-cli.exe', 'docs/readme.txt', 'empty.txt'])
    expect(directory.archiveBytes).toBe((await stat(archive)).size)
    expect(directory.totalUncompressed).toBe(800 + 13)
    // `zipSync` deflates; a zero-length entry may be stored instead.
    expect(directory.entries.every(entry => entry.method === 0 || entry.method === 8)).toBe(true)
    expect(directory.entries[0]?.method).toBe(8)
  })

  it('reads one entry byte-exact, including a zero-length one', async () => {
    const archive = await write('entry.zip', flatArchive())
    const directory = await readZipDirectory(archive)
    const first = directory.entries[0]
    expect(first).toBeDefined()
    if (first === undefined) return
    expect((await readZipEntry(archive, first)).toString()).toBe('MZ'.repeat(400))
    const empty = directory.entries[2]
    expect(empty).toBeDefined()
    if (empty === undefined) return
    expect((await readZipEntry(archive, empty)).length).toBe(0)
  })

  it('extracts a whole tree and reports what it wrote', async () => {
    const archive = await write('extract.zip', flatArchive())
    const target = join(root, 'out-flat')
    const result = await extractZip(archive, target)
    expect(result.files).toBe(3)
    expect(await readFile(join(target, 'docs', 'readme.txt'), 'utf8')).toBe('KiCad HuaQiu\n')
    // The empty entry is written as an empty file; a zero-length *deflated* entry
    // used to abort extraction with an out-of-range stream range.
    expect((await stat(join(target, 'empty.txt'))).size).toBe(0)
  })

  it('strips the archive prefix the common-directory helper finds', async () => {
    const archive = await write('rooted.zip', zipSync({
      'kicad-huaqiu-10.0.7-2/bin/kicad-cli.exe': new TextEncoder().encode('MZ'),
      'kicad-huaqiu-10.0.7-2/docs/readme.txt': new TextEncoder().encode('doc'),
    }))
    const directory = await readZipDirectory(archive)
    const files = directory.entries.filter(entry => !entry.directory)
    expect(commonDirectory({ ...directory, entries: files })).toBe('kicad-huaqiu-10.0.7-2/')
    const target = join(root, 'out-rooted')
    const result = await extractZip(archive, target, { directory, stripPrefix: 'kicad-huaqiu-10.0.7-2/' })
    expect(result.files).toBe(2)
    expect(await readFile(join(target, 'bin', 'kicad-cli.exe'), 'utf8')).toBe('MZ')
  })

  it('reports no common directory for the real distribution shape', () => {
    // The KiCad zip has no single root: `bin/` and `docs/` sit at the top level.
    expect(commonDirectory({
      entries: [
        { name: 'bin/kicad-cli.exe', compressedSize: 1, uncompressedSize: 1, method: 8, headerOffset: 0, directory: false },
        { name: 'docs/readme.txt', compressedSize: 1, uncompressedSize: 1, method: 8, headerOffset: 1, directory: false },
      ],
      totalUncompressed: 2,
      archiveBytes: 2,
    })).toBeUndefined()
  })

  it('refuses traversal, absolute and device paths', () => {
    expect(() => safeEntrySegments('../etc/passwd')).toThrow(ZipError)
    expect(() => safeEntrySegments('/etc/passwd')).toThrow(ZipError)
    expect(() => safeEntrySegments('C:/Windows/system32')).toThrow(ZipError)
    expect(() => safeEntrySegments('bin\\con.exe')).toThrow(ZipError)
    expect(() => safeEntrySegments('bin/file.txt:stream')).toThrow(ZipError)
    expect(safeEntrySegments('bin\\kicad-cli.exe')).toEqual(['bin', 'kicad-cli.exe'])
    // A redundant `.` and an empty segment are normal shapes, not hostile ones.
    expect(safeEntrySegments('./bin//kicad-cli.exe')).toEqual(['bin', 'kicad-cli.exe'])
    expect(() => safeEntrySegments('./bin//tools/../x')).toThrow(ZipError)
  })

  it('refuses an archive that exceeds the entry budget', async () => {
    const archive = await write('many.zip', flatArchive())
    await expect(extractZip(archive, join(root, 'out-many'), {
      limits: { maxEntries: 2 },
    })).rejects.toMatchObject({ code: 'archive-too-large' })
  })

  it('refuses an entry that exceeds the per-file budget', async () => {
    const archive = await write('big.zip', flatArchive())
    await expect(extractZip(archive, join(root, 'out-big'), {
      limits: { maxEntryBytes: 100 },
    })).rejects.toMatchObject({ code: 'archive-too-large' })
  })

  it('honours a pre-cancelled signal before writing anything', async () => {
    const archive = await write('cancel.zip', flatArchive())
    const controller = new AbortController()
    controller.abort()
    await expect(extractZip(archive, join(root, 'out-cancel'), { signal: controller.signal }))
      .rejects.toMatchObject({ code: 'cancelled' })
  })

  it('keeps a generous default budget so the real 840 MB archive fits', () => {
    expect(DEFAULT_ZIP_LIMITS.maxEntryBytes).toBeGreaterThan(1024 ** 3)
    expect(DEFAULT_ZIP_LIMITS.maxEntries).toBeGreaterThan(99_460)
  })
})
